-- F1.23b: normalize legacy global user identifier comparison, preserving grants and safeguards.
DO $repair$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.set_organization_member_status(text,uuid,uuid,text,text,text,text,text)'::regprocedure) INTO definition; IF position('ur.user_id=actor_user_id' in definition)>0 THEN EXECUTE replace(definition,'ur.user_id=actor_user_id','ur.user_id::text=actor_user_id::text'); ELSIF position('ur.user_id::text=actor_user_id::text' in definition)=0 THEN RAISE EXCEPTION 'Unexpected function definition'; END IF; END $repair$; NOTIFY pgrst,'reload schema';
